/**
 * QR encoder with D4's pinned mask pattern.
 *
 * D4 specifies using node-qrcode with a pinned mask pattern for 4.6-8× encode speedup.
 * The encoder pins the mask pattern to a fixed value (default: 0) instead of evaluating
 * all 8 mask patterns to choose the "best" one.
 *
 * Per plan.md §6.3.1: "On-demand is cheap. ~0.29 ms per v15 tile (from 1.53 ms at v40,
 * mask pinned) × 15 tiles × 15 fps ≈ 65 ms/sec, ~7% of one core"
 *
 * This module provides the QR encoding utilities that will be used by the modulation layer.
 */

import QRCode from 'qrcode';

/**
 * QR encoder configuration with pinned mask pattern.
 */
export interface QREncoderConfig {
  /** QR version (1-40) */
  version: number;
  /** Error correction level (always 'L' per plan - redundancy belongs in fountain code) */
  errorCorrectionLevel: 'L' | 'M' | 'Q' | 'H';
  /** Mask pattern (0-7). Default: 0 (pinned per D4) */
  maskPattern?: number;
}

/**
 * Default QR encoder configuration with D4's pinned mask.
 */
export const DEFAULT_QR_CONFIG: QREncoderConfig = {
  version: 15, // R2 nominal
  errorCorrectionLevel: 'L',
  maskPattern: 0, // D4: pinned mask for 4.6-8× speedup
};

/**
 * Encode data into a QR code matrix with pinned mask pattern.
 *
 * @param data - Binary data to encode
 * @param config - QR encoder configuration
 * @returns QR code matrix
 */
export function encodeQRMatrix(data: Uint8Array, config: QREncoderConfig = DEFAULT_QR_CONFIG): QRCode {
  const segments = [{ data: Array.from(data), mode: 'byte' as const }];

  return QRCode.create(segments, {
    errorCorrectionLevel: config.errorCorrectionLevel,
    version: config.version,
    maskPattern: config.maskPattern ?? 0, // D4: pinned mask
  });
}

/**
 * Get QR module size for a given version.
 *
 * @param version - QR version (1-40)
 * @returns Number of modules per side (version * 4 + 17)
 */
export function getQRModuleSize(version: number): number {
  return version * 4 + 17;
}

/**
 * Calculate optimal QR version for packet data size.
 *
 * Per plan.md §3.1.1: "pick L to fit the smallest tile any profile would use"
 * The QR version is chosen based on packetsPerTile and L (fragment length).
 *
 * @param packetBytes - Size of one packet including header (typically 269 bytes)
 * @param packetsPerTile - Number of packets per tile (1-4)
 * @param maxVersion - Maximum QR version to consider (default: 40)
 * @returns QR version that fits the data
 */
export function calculateQRVersion(
  packetBytes: number,
  packetsPerTile: number,
  maxVersion: number = 40
): number {
  const totalBytes = packetBytes * packetsPerTile;

  // Find smallest version that can fit the data at ECC level L
  for (let v = 1; v <= maxVersion; v++) {
    const capacity = getQRCapacity(v, 'L');
    if (capacity >= totalBytes) {
      return v;
    }
  }

  throw new Error(`Data size ${totalBytes} bytes exceeds QR ${maxVersion}-L capacity`);
}

/**
 * Get QR capacity in bytes for a given version and ECC level.
 *
 * @param version - QR version (1-40)
 * @param eccLevel - Error correction level
 * @returns Maximum data bytes
 */
function getQRCapacity(version: number, eccLevel: 'L' | 'M' | 'Q' | 'H'): number {
  // Capacity table for QR codes (from QR code specification)
  const capacities: Record<number, Record<string, number>> = {
    10: { L: 174, M: 138, Q: 100, H: 74 },
    15: { L: 421, M: 335, Q: 243, H: 179 },
    16: { L: 477, M: 379, Q: 275, H: 203 },
    20: { L: 774, M: 617, Q: 447, H: 331 },
    23: { L: 1006, M: 802, Q: 581, H: 431 },
  };

  const versionCapacities: Record<number, number> = {
    1: 41, 2: 58, 3: 85, 4: 108, 5: 136,
    6: 174, 7: 187, 8: 219, 9: 259, 10: 312,
    11: 364, 12: 434, 13: 488, 14: 596, 15: 692,
    16: 800, 17: 912, 18: 1056, 19: 1208, 20: 1376,
    21: 1552, 22: 1744, 23: 1976, 24: 2224, 25: 2544,
    26: 2864, 27: 3232, 28: 3616, 29: 4096, 30: 4576,
    31: 5104, 32: 5632, 33: 6256, 34: 6864, 35: 7504,
    36: 8256, 37: 9008, 38: 9776, 39: 10624, 40: 11488
  };

  // Apply ECC level penalty (approximate)
  const baseCapacity = versionCapacities[version];
  if (!baseCapacity) {
    throw new Error(`Invalid QR version: ${version}`);
  }

  // ECC level penalties (L=1.0, M≈0.8, Q≈0.6, H≈0.45)
  const eccPenalty: Record<string, number> = {
    L: 1.0,
    M: 0.8,
    Q: 0.6,
    H: 0.45,
  };

  return Math.floor(baseCapacity * eccPenalty[eccLevel]);
}

/**
 * QR encoding worker with D4's pinned mask pattern.
 *
 * Per plan.md §6.3.1: "Implementation: worker generator → ring buffer (depth 3) →
 * main thread paints via rAF. Deeper buffering is wasted memory (I7)."
 *
 * This worker performs QR encoding with pinned mask pattern for 4.6-8× speedup.
 * It receives packets and renders them to ImageData for canvas display.
 */

import { encodeQRMatrix, getQRModuleSize } from '../modulation/qr-tiled/qr-encoder.js';

/** Worker message types */
interface EncodeRequest {
  type: 'encode';
  packets: Uint8Array[];
  version: number;
  modulePx: number;
}

interface EncodeResponse {
  type: 'encoded';
  tiles: ImageData[];
}

/** Render QR matrix to ImageData at specified module pixel size */
function renderQRToImageData(matrix: any, modulePx: number): ImageData {
  const size = matrix.modules.size;
  const data = matrix.modules.data;

  const width = size * modulePx;
  const height = size * modulePx;
  const imageData = new ImageData(width, height);

  // Each module becomes modulePx × modulePx pixels
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const isDark = data[y * size + x];
      const color = isDark ? 0 : 255; // Black or white (dark-on-light per D12)

      // Fill the module's pixels
      for (let py = 0; py < modulePx; py++) {
        for (let px = 0; px < modulePx; px++) {
          const imgIdx = ((y * modulePx + py) * width + (x * modulePx + px)) * 4;
          imageData.data[imgIdx] = color;     // R
          imageData.data[imgIdx + 1] = color; // G
          imageData.data[imgIdx + 2] = color; // B
          imageData.data[imgIdx + 3] = 255;   // A
        }
      }
    }
  }

  return imageData;
}

/** Handle incoming messages from main thread */
self.onmessage = (e: MessageEvent): void => {
  const request: EncodeRequest = e.data;

  if (request.type === 'encode') {
    try {
      const tiles: ImageData[] = [];

      for (const packet of request.packets) {
        // Encode QR with pinned mask pattern (D4)
        const matrix = encodeQRMatrix(packet, {
          version: request.version,
          errorCorrectionLevel: 'L',
          maskPattern: 0, // D4: pinned mask for 4.6-8× speedup
        });

        // Render to ImageData
        const imageData = renderQRToImageData(matrix, request.modulePx);
        tiles.push(imageData);
      }

      // Send encoded tiles back to main thread
      const response: EncodeResponse = { type: 'encoded', tiles };
      self.postMessage(response);
    } catch (error) {
      // Propagate encoding errors back to main thread
      self.postMessage({
        type: 'error',
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }
};

export {};

/**
 * QR encoder worker manager with D4's pinned mask pattern.
 *
 * Manages a pool of QR encoding workers with pinned mask pattern for 4.6-8× speedup.
 * Provides a high-level API for the modulation layer to encode packets to ImageData.
 */

/** QR encoding request */
export interface QREncodeRequest {
  packets: Uint8Array[];
  version: number;
  modulePx: number;
}

/** QR encoding result */
export interface QREncodeResult {
  tiles: ImageData[];
}

/**
 * QR encoder worker manager.
 *
 * Manages a pool of workers for parallel QR encoding with pinned mask pattern.
 */
export class QREncoderWorkerManager {
  private workers: Worker[] = [];
  private nextWorkerIndex = 0;

  /**
   * Create a QR encoder worker manager.
   *
   * @param poolSize - Number of workers to create (default: navigator.hardwareConcurrency || 4)
   */
  constructor(poolSize: number = navigator.hardwareConcurrency || 4) {
    for (let i = 0; i < poolSize; i++) {
      const worker = new Worker(
        new URL('../../workers/qr-encode.worker.ts', import.meta.url),
        { type: 'module' }
      );
      this.workers.push(worker);
    }
  }

  /**
   * Encode packets to QR tiles using worker pool.
   *
   * @param request - QR encoding request
   * @returns Promise resolving to encoded tiles
   */
  async encode(request: QREncodeRequest): Promise<QREncodeResult> {
    const worker = this.getNextWorker();

    return new Promise((resolve, reject) => {
      const handleMessage = (e: MessageEvent): void => {
        if (e.data.type === 'encoded') {
          worker.removeEventListener('message', handleMessage);
          resolve({ tiles: e.data.tiles });
        } else if (e.data.type === 'error') {
          worker.removeEventListener('message', handleMessage);
          reject(new Error(e.data.error));
        }
      };

      worker.addEventListener('message', handleMessage);

      worker.postMessage({
        type: 'encode',
        packets: request.packets,
        version: request.version,
        modulePx: request.modulePx,
      });
    });
  }

  /**
   * Get next worker in round-robin fashion.
   */
  private getNextWorker(): Worker {
    const worker = this.workers[this.nextWorkerIndex];
    this.nextWorkerIndex = (this.nextWorkerIndex + 1) % this.workers.length;
    return worker;
  }

  /**
   * Terminate all workers.
   */
  destroy(): void {
    for (const worker of this.workers) {
      worker.terminate();
    }
    this.workers = [];
  }
}

